#include <iostream>
#include <cstdio>
using namespace std;

const int MOD = 1000000007;
const int MAX = 1010;

void add(int &x, long long y) {
    x = (x + y) % MOD;
}

inline int read() {
    int x = 0;
    bool negative = false;
    int ch = getchar();

    while ((ch < '0' || ch > '9') && ch != '-' && ch != EOF)
        ch = getchar();

    if (ch == '-') {
        negative = true;
        ch = getchar();
    }

    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }

    return negative ? -x : x;
}

int n, m, jc[MAX], a[MAX], ans;
int f[MAX][MAX][4], C[MAX][MAX];

int main() {
    n = read();
    m = read();

    jc[0] = 1;
    for (int i = 1; i <= n; ++i)
        jc[i] = 1LL * jc[i - 1] * i % MOD;

    for (int i = 0; i <= n; ++i)
        C[i][0] = 1;

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= i; ++j)
            C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % MOD;

    f[0][0][1] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            for (int S = 0; S < 4; ++S) {
                if (!f[i - 1][j][S])
                    continue;

                add(f[i][j][S >> 1], f[i - 1][j][S]);

                if (!(S & 1))
                    add(f[i][j + 1][S >> 1], f[i - 1][j][S]);

                if (i != n)
                    add(f[i][j + 1][(S >> 1) | 2], f[i - 1][j][S]);
            }
        }
    }

    for (int i = 0; i <= n; ++i)
        for (int S = 0; S < 4; ++S)
            add(a[i], 1LL * f[n][i][S] * jc[n - i] % MOD);

    for (int i = m, d = 1; i <= n; ++i, d = MOD - d)
        add(ans, 1LL * d * C[i][m] % MOD * a[i] % MOD);

    printf("%d\n", ans);
    return 0;
}

#include <cstdio>

constexpr int MOD = 1000000007;
constexpr int MAXN = 1010;

int n, m;
int factorial[MAXN], a[MAXN], answer;
int dp[MAXN][MAXN][4];
int combination[MAXN][MAXN];

inline int readInt() {
    int x = 0, sign = 1;
    int ch = getchar();

    while (ch != '-' && (ch < '0' || ch > '9')) ch = getchar();
    if (ch == '-') {
        sign = -1;
        ch = getchar();
    }

    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x * sign;
}

inline void addMod(int& x, long long y) {
    x = static_cast<int>((x + y) % MOD);
}

int main() {
    n = readInt();
    m = readInt();

    factorial[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorial[i] = static_cast<int>(1LL * factorial[i - 1] * i % MOD);
    }

    for (int i = 0; i <= n; ++i) combination[i][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            combination[i][j] =
                (combination[i - 1][j] + combination[i - 1][j - 1]) % MOD;
        }
    }

    dp[0][0][1] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            for (int state = 0; state < 4; ++state) {
                int current = dp[i - 1][j][state];
                if (current == 0) continue;

                addMod(dp[i][j][state >> 1], current);

                if (!(state & 1)) {
                    addMod(dp[i][j + 1][state >> 1], current);
                }

                if (i != n) {
                    addMod(dp[i][j + 1][(state >> 1) | 2], current);
                }
            }
        }
    }

    for (int i = 0; i <= n; ++i) {
        for (int state = 0; state < 4; ++state) {
            addMod(a[i], 1LL * dp[n][i][state] * factorial[n - i] % MOD);
        }
    }

    for (int i = m, sign = 1; i <= n; ++i, sign = MOD - sign) {
        addMod(answer, 1LL * sign * combination[i][m] % MOD * a[i] % MOD);
    }

    printf("%d\n", answer);
    return 0;
}

